{
  "findings": [
    {
      "check_id": "CKV2_AWS_11",
      "title": "VPC flow logging is not enabled",
      "resource": "aws_vpc.changeme_aws_vpc_simple",
      "severity": "MEDIUM",
      "explanation": "The VPC has no flow log configured, reducing visibility into accepted and rejected network traffic and hindering incident investigation."
    },
    {
      "check_id": "CKV2_AWS_12",
      "title": "Default security group does not explicitly restrict traffic",
      "resource": "aws_vpc.changeme_aws_vpc_simple",
      "severity": "MEDIUM",
      "explanation": "The VPC's implicitly created default security group retains provider defaults unless it is explicitly managed, allowing unrestricted outbound traffic and traffic between resources assigned to that group."
    }
  ],
  "patched_code": "variable "vpc_flow_log_s3_destination_arn" {
  description = "ARN of an existing access-controlled S3 bucket used to store VPC flow logs."
  type        = string
}

resource "aws_vpc" "changeme_aws_vpc_simple" {
  cidr_block = "10.1.0.0/16"
}

resource "aws_default_security_group" "changeme_aws_vpc_simple" {
  vpc_id = aws_vpc.changeme_aws_vpc_simple.id
}

resource "aws_flow_log" "changeme_aws_vpc_simple" {
  vpc_id                   = aws_vpc.changeme_aws_vpc_simple.id
  traffic_type             = "ALL"
  log_destination_type     = "s3"
  log_destination          = var.vpc_flow_log_s3_destination_arn
  max_aggregation_interval = 60
}
",
  "fix_summary": "Enabled VPC flow logging for all traffic using a caller-supplied S3 destination ARN. Explicitly managed the VPC's default security group with no ingress or egress rules."
}
